// ============================================================
// Build Final Chat Response
// 1. Extracts and parses the AI JSON output.
// 2. Normalizes array/object responses.
// 3. Returns the exact contract expected by the Backend.
// ============================================================

const inputData = $input.first().json;

// IMPORTANT:
// Replace "Webhook" below with the exact name of your Webhook node.
const webhookInput = $('Chat Webhook').first().json;

// ------------------------------------------------------------
// 1. Get the original request ID sent by the Backend
// ------------------------------------------------------------

const requestId =
  webhookInput?.body?.request?.id ??
  webhookInput?.body?.requestId ??
  webhookInput?.request?.id ??
  webhookInput?.requestId;

if (
  typeof requestId !== 'string' ||
  requestId.trim().length === 0
) {
  throw new Error(
    'CHAT_RESPONSE_BUILD_ERROR: Original requestId is missing'
  );
}

// ------------------------------------------------------------
// 2. Extract raw AI output
// ------------------------------------------------------------

let rawContent;

if (typeof inputData === 'string') {
  rawContent = inputData;
} else if (typeof inputData?.text === 'string') {
  rawContent = inputData.text;
} else if (typeof inputData?.output?.content === 'string') {
  rawContent = inputData.output.content;
} else if (typeof inputData?.content === 'string') {
  rawContent = inputData.content;
} else if (
  typeof inputData?.choices?.[0]?.message?.content === 'string'
) {
  rawContent = inputData.choices[0].message.content;
} else if (typeof inputData?.message?.content === 'string') {
  rawContent = inputData.message.content;
} else {
  // The previous node may already have parsed the JSON.
  rawContent = inputData;
}

// ------------------------------------------------------------
// 3. Parse JSON when the input is still a string
// ------------------------------------------------------------

let parsed;

if (typeof rawContent === 'string') {
  let cleaned = rawContent
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .replace(
      /[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g,
      ''
    )
    .trim();

  if (!cleaned) {
    throw new Error(
      'CHAT_RESPONSE_BUILD_ERROR: AI response is empty'
    );
  }

  try {
    parsed = JSON.parse(cleaned);
  } catch (firstError) {
    // Try extracting the outermost JSON object or array.
    const objectStart = cleaned.indexOf('{');
    const objectEnd = cleaned.lastIndexOf('}');
    const arrayStart = cleaned.indexOf('[');
    const arrayEnd = cleaned.lastIndexOf(']');

    let extracted = null;

    if (
      arrayStart !== -1 &&
      arrayEnd > arrayStart &&
      (objectStart === -1 || arrayStart < objectStart)
    ) {
      extracted = cleaned.slice(arrayStart, arrayEnd + 1);
    } else if (objectStart !== -1 && objectEnd > objectStart) {
      extracted = cleaned.slice(objectStart, objectEnd + 1);
    }

    if (!extracted) {
      throw new Error(
        `CHAT_RESPONSE_PARSE_ERROR: ${firstError.message}`
      );
    }

    try {
      parsed = JSON.parse(extracted);
    } catch (secondError) {
      throw new Error(
        `CHAT_RESPONSE_PARSE_ERROR: ${secondError.message}`
      );
    }
  }
} else {
  parsed = rawContent;
}

// ------------------------------------------------------------
// 4. Normalize array output
// Your current AI output is: [ { intent: {...}, ... } ]
// ------------------------------------------------------------

if (Array.isArray(parsed)) {
  if (parsed.length === 0) {
    throw new Error(
      'CHAT_RESPONSE_BUILD_ERROR: AI returned an empty array'
    );
  }

  parsed = parsed[0];
}

if (
  parsed === null ||
  typeof parsed !== 'object' ||
  Array.isArray(parsed)
) {
  throw new Error(
    'CHAT_RESPONSE_BUILD_ERROR: AI result must be an object'
  );
}

// ------------------------------------------------------------
// 5. Validate key AI fields
// ------------------------------------------------------------

const summary =
  typeof parsed.summary === 'string'
    ? parsed.summary.trim()
    : '';

const analysis =
  typeof parsed.analysis === 'string'
    ? parsed.analysis.trim()
    : '';

const advice =
  typeof parsed.advice === 'string'
    ? parsed.advice.trim()
    : '';

const replyParts = [summary, analysis, advice].filter(
  value => value.length > 0
);

if (replyParts.length === 0) {
  throw new Error(
    'CHAT_RESPONSE_BUILD_ERROR: AI returned no usable reply'
  );
}

const reply = replyParts.join('\n\n');

// Apply a safe maximum reply length.
// Adjust this only if the Backend validator uses another documented maximum.
const MAX_REPLY_LENGTH = 12000;

if (reply.length > MAX_REPLY_LENGTH) {
  throw new Error(
    'CHAT_RESPONSE_BUILD_ERROR: AI reply exceeds the allowed length'
  );
}

// ------------------------------------------------------------
// 6. Normalize metadata
// ------------------------------------------------------------

const primaryIntent =
  typeof parsed?.intent?.primary === 'string'
    ? parsed.intent.primary
    : 'general_financial_advice';

const secondaryIntents = Array.isArray(
  parsed?.intent?.secondary
)
  ? parsed.intent.secondary.filter(
      value => typeof value === 'string'
    )
  : [];

const scenarios = Array.isArray(parsed.scenarios)
  ? parsed.scenarios
  : [];

const suggestedQuestions = Array.isArray(
  parsed.suggestedQuestions
)
  ? parsed.suggestedQuestions
      .filter(value => typeof value === 'string')
      .map(value => value.trim())
      .filter(Boolean)
      .slice(0, 5)
  : [];

const confidence =
  typeof parsed.confidence === 'number' &&
  Number.isFinite(parsed.confidence)
    ? Math.max(0, Math.min(100, parsed.confidence))
    : null;

const followUp = {
  required: parsed?.followUp?.required === true,
  question:
    typeof parsed?.followUp?.question === 'string'
      ? parsed.followUp.question.trim()
      : '',
};

// ------------------------------------------------------------
// 7. Return exact Backend contract
// IMPORTANT:
// intent must be the string "chat", not the AI intent object.
// ------------------------------------------------------------

return [
  {
    json: {
      success: true,
      requestId: requestId.trim(),
      reply,
      intent: 'chat',
      providerExecutionId: String($execution.id),
      metadata: {
        primaryIntent,
        secondaryIntents,
        responseType:
          typeof parsed.responseType === 'string'
            ? parsed.responseType
            : 'guidance',
        confidence,
        responseLanguage:
          typeof parsed.responseLanguage === 'string'
            ? parsed.responseLanguage
            : 'ar',
        scenarios,
        suggestedQuestions,
        followUp,
      },
    },
  },
];

// ============================================================
// Alpha — Build Financial Context (الإصدار المُحسَّن)
// ============================================================

const data = $input.item.json;
const monthlyIncome = data.financial?.monthlyIncome || 0;
const goals = data.goals || [];
const transactions = data.recentTransactions || [];
const currentCycle = data.currentCycle || {};
const financial = data.financial || {};
const user = data.user || {};

// ============================================================
// 1. دالة تحديد الشريحة المالية
// ============================================================
function getIncomeTier(income) {
    if (income < 300) return { tier: 'منخفض جداً', needs: 0.8, wants: 0.15, savings: 0.05 };
    if (income < 450) return { tier: 'منخفض', needs: 0.7, wants: 0.2, savings: 0.1 };
    if (income < 750) return { tier: 'متوسط أدنى', needs: 0.6, wants: 0.25, savings: 0.15 };
    if (income < 1200) return { tier: 'متوسط', needs: 0.5, wants: 0.3, savings: 0.2 };
    if (income < 2000) return { tier: 'متوسط أعلى', needs: 0.4, wants: 0.35, savings: 0.25 };
    if (income < 3000) return { tier: 'مرتفع', needs: 0.3, wants: 0.4, savings: 0.3 };
    return { tier: 'مرتفع جداً', needs: 0.2, wants: 0.45, savings: 0.35 };
}

// ============================================================
// 2. حساب المؤشرات المالية الأساسية
// ============================================================
const tier = getIncomeTier(monthlyIncome);

// الميزانية المثالية
const idealBudget = {
    needs: Math.round(monthlyIncome * tier.needs),
    wants: Math.round(monthlyIncome * tier.wants),
    savings: Math.round(monthlyIncome * tier.savings)
};

// صندوق الطوارئ (قراءة من البيانات إن وجدت، وإلا افتراض 0)
const currentEmergencyFund = data.emergencyFund?.current || 0;
const emergencyFundTarget = idealBudget.needs * 3;

let emergencyContribution = 0;
let savingsAfterEmergency = idealBudget.savings;

if (currentEmergencyFund < emergencyFundTarget) {
    emergencyContribution = Math.min(idealBudget.savings * 0.7, emergencyFundTarget - currentEmergencyFund);
    savingsAfterEmergency = idealBudget.savings - emergencyContribution;
}

// ============================================================
// 3. تحليل الأهداف
// ============================================================
let goalAnalysis = null;
let hasActiveGoal = false;

if (goals.length > 0) {
    const activeGoal = goals.find(g => g.status === 'active') || goals[0];
    hasActiveGoal = true;
    const remaining = activeGoal.targetAmount - activeGoal.savedAmount;

    let monthsNeeded = null;
    let expectedDate = null;

    if (savingsAfterEmergency > 0 && remaining > 0) {
        monthsNeeded = Math.ceil(remaining / savingsAfterEmergency);
        expectedDate = new Date();
        expectedDate.setMonth(expectedDate.getMonth() + monthsNeeded);
    }

    goalAnalysis = {
        name: activeGoal.name,
        targetAmount: activeGoal.targetAmount,
        savedAmount: activeGoal.savedAmount,
        remainingAmount: remaining,
        targetDate: activeGoal.targetDate,
        monthsNeeded: monthsNeeded,
        expectedDate: expectedDate
    };
}

// ============================================================
// 4. تحديد النية ونوع الرد
// ============================================================
let primaryIntent = 'general_financial_advice';
let responseType = 'guidance';

if (hasActiveGoal && goalAnalysis && goalAnalysis.remainingAmount > 0) {
    primaryIntent = 'goal_planning';
    responseType = 'analysis';
} else if (hasActiveGoal && goalAnalysis && goalAnalysis.remainingAmount === 0) {
    primaryIntent = 'saving';
    responseType = 'guidance';
} else if (currentEmergencyFund < emergencyFundTarget) {
    primaryIntent = 'saving';
    responseType = 'analysis';
}

// ============================================================
// 5. بناء الكائن النهائي (المُحسَّن)
// ============================================================
const result = {
    // --- معلومات المستخدم ---
    user: {
        name: user.name || null,
        currency: user.currency || 'JOD'
    },

    // --- البيانات المالية الأساسية ---
    financialData: {
        monthlyIncome: monthlyIncome,
        monthlyEssentialExpenses: financial.needs?.spent || 0,
        monthlyWants: financial.wants?.spent || 0,
        monthlySavings: financial.savings?.saved || 0,
        currentEmergencyFund: currentEmergencyFund,
        goalTargetAmount: goalAnalysis?.targetAmount || null,
        goalSavedAmount: goalAnalysis?.savedAmount || null,
        goalRemaining: goalAnalysis?.remainingAmount || null,
        goalTargetDate: goalAnalysis?.targetDate || null,
        totalMonthlyDebt: financial.commitments?.monthly || 0,

        // التزامات مفصلة
        commitments: {
            monthly: financial.commitments?.monthly || 0,
            unpaid: financial.commitments?.unpaid || 0
        },

        // سياق العملة
        currencyContext: {
            profileCurrency: user.currency || 'JOD',
            mentionedCurrencies: [user.currency || 'JOD'],
            requiresCurrencyConversion: false,
            exchangeRateAvailable: true
        }
    },

    // --- المؤشرات المحسوبة مسبقاً ---
    computed: {
        incomeTier: tier.tier,
        idealBudget: idealBudget,
        emergencyFund: {
            target: Math.round(emergencyFundTarget),
            current: currentEmergencyFund,
            monthlyContribution: Math.round(emergencyContribution),
            isAdequate: currentEmergencyFund >= emergencyFundTarget
        },
        savingsCapacity: {
            totalMonthlySavings: idealBudget.savings,
            availableForGoalsAfterEmergency: Math.round(savingsAfterEmergency)
        },
        goalProjection: goalAnalysis ? {
            monthsToAchieve: goalAnalysis.monthsNeeded,
            expectedCompletionDate: goalAnalysis.expectedDate 
                ? goalAnalysis.expectedDate.toISOString().split('T')[0] 
                : null
        } : null
    },

    // --- سياق التحليل (للـ AI) ---
    analysisContext: {
        primaryIntent: primaryIntent,
        responseType: responseType,
        hasActiveGoal: hasActiveGoal,
        emergencyFundShortfall: Math.max(0, emergencyFundTarget - currentEmergencyFund)
    },

    // --- ✅ معلومات الدورة الشهرية (جديدة) ---
    currentCycle: {
        status: currentCycle.status || null,
        elapsedDays: currentCycle.elapsedDays || null,
        remainingDays: currentCycle.remainingDays || null,
        totalDays: currentCycle.totalDays || null
    },

    // --- ✅ تحليلات مالية إضافية (جديدة) ---
    financialAnalytics: {
        projectedExpenses: financial.analytics?.projectedExpenses || null,
        safeDailySpend: financial.analytics?.safeDailySpend || null,
        totalSpent: financial.overall?.totalSpent || 0,
        remainingBudget: financial.overall?.remainingBudget || 0
    },

    // --- المعاملات الأخيرة ---
    recentTransactions: transactions
};

// ============================================================
// 6. الإخراج النهائي
// ============================================================
return [
    {
        json: {
            financialContext: JSON.stringify(result, null, 2)
        }
    }
];
